// across GitHub Pages, AI Studio preview iframes, and PDF canvas generation.

export const CEMET_LOGO_SRC = "data:image/png;base64,";
export const FIRMA_SELLO_SRC = "data:image/png;base64,";

export const getCemetLogoUrl = () => {
  return CEMET_LOGO_SRC;
};
